INSERT INTO `ExampleSentence` (`id`, `kanjiId`, `japanese`, `romaji`, `translation`, `isReading`) VALUES
(6939, 3213, '明日の試験はとても難しいですから、頑張ってください。', 'Ashita no shiken wa totemo muzukashii desu kara, ganbatte kudasai.', 'Karena ujian besok sangat sulit, berjuanglah.', 1),
(6940, 3213, '来月、日本語能力試験(JLPT)を 受検しようと 思っています。', 'Raigetsu, nihongo nouryoku shiken (JLPT) wo juken shiyou to omotteimasu.', 'Bulan depan, saya berencana mengikuti Ujian Kemampuan Bahasa Jepang (JLPT).', 1),
(6941, 3213, '毎日 この 薬を 飲めば、すぐに 効験が 現れるでしょう。', 'Mainichi kono kusuri wo nomeba, suguni kouken ga arawareru deshou.', 'Jika Anda minum obat ini setiap hari, khasiatnya akan segera terlihat.', 1),
(6942, 3213, '日本へ留学したことは、私にとって良い経験になりました。', 'Nihon he ryuugaku shita koto wa, watashi ni totte yoi keiken ni narimashita.', 'Belajar di Jepang telah menjadi pengalaman yang baik bagi saya.', 1),
(6943, 3213, '化学ので, 水の性質を調べる実験を行いました。', 'Kagaku no jugyou de, mizu no seishitsu wo shiraberu jikken wo okonaimashita.', 'Dalam kelas kimia, kami melakukan eksperimen untuk memeriksa sifat-sifat air.', 1),
(6949, 3215, '宿題が多すぎて、昨日は寝る時間がありませんでした。', 'Shukudai ga oosugite, kinou wa neru jikan ga arimasen deshita.', 'Karena PR terlalu banyak, kemarin saya tidak punya waktu tidur.', 1),
(6950, 3215, '今日のゼミでは、卒業論文の論題について議論します。', 'Kyou no zemi dewa, sotsugyou ronbun no rondai ni tsuite giron shimasu.', 'Di seminar hari ini, kami akan mendiskusikan tema tesis kelulusan.', 1),
(6951, 3215, '会議で 面白い 話題が 出ています。', 'Kaigi de omoshiroi wadai ga deteimasu.', 'Dalam rapat, muncul topik yang menarik.', 1),
(6952, 3215, '彼女は自分の留学経験を題材にして小説を書きました。', 'Kanojo wa jibun no ryuugaku keiken wo daizai ni shite shousetsu wo kakimashita.', 'Dia menulis novel berdasarkan pengalaman belajarnya di luar negeri.', 1),
(6953, 3215, '今週は課題がたくさんありますから、とても忙しいです。', 'Konshuu wa kadai ga takusan arimasu kara, totemo isogashii desu.', 'Karena minggu ini ada banyak tugas, saya sangat sibuk.', 1),
