(7096, 3212, '来週、日本語の試験がありますから、今晩から準備します。', 'Raishuu, nihongo no shiken ga arimasu kara, konban kara junbi shimasu.', 'Karena minggu depan ada ujian bahasa Jepang, saya akan bersiap-siap mulai malam ini.', 0),
(7097, 3212, '服を買う前に、お店のここで試着することができます。', 'Fuku wo kau mae ni, omise no koko de shichaku suru koto ga dekimasu.', 'Sebelum membeli pakaian, Anda dapat mencobanya di bagian toko ini.', 0),
(7098, 3212, 'この新しいアプリは、1か月無料で試用できます。', 'Kono atarashii apuri wa, ikkagetsu muryou de shiyou dekimasu.', 'Aplikasi baru ini dapat dicoba secara gratis selama 1 bulan.', 0),
(7099, 3212, 'デパ地下で新しいケーキの試食をしました。', 'Depachika de atarashii keeki no shishoku wo shimashita.', 'Saya mencicipi kue baru di lantai bawah tanah department store.', 0),
(7100, 3212, '新しいジュースの試飲をお客さんにしてもらいます。', 'Atarashii juusu no shiin wo okyakusan ni shitemoraimasu.', 'Kami meminta pelanggan untuk mencicipi jus baru.', 0),
(7116, 3221, '体調が 悪い ときは、無理を しない ほうが いいです。', 'Taichou ga warui toki wa, muri wo shinai hou ga ii desu.', 'Saat kondisi tubuh buruk, sebaiknya jangan memaksakan diri.', 0),
(7117, 3221, 'ラジオを 聞きながら 野菜を 調理します。', 'Rajio wo kikinagara yasai wo chouri shimasu.', 'Sambil mendengarkan radio, saya memasak sayuran.', 0),
(7118, 3221, 'インターネットで 辞書の 意味を 調べようと 思っています。', 'Intaanetto de jisho no imi wo shirabeyou to omotte imasu.', 'Saya berencana mencari arti kamus lewat internet.', 0),
(7119, 3221, 'パソコンの 調子が 悪いですから、不調に なるかもしれません。', 'Pasokon no choushi ga warui desu kara, fuchou ni naru kamo shiremasen.', 'Karena kondisi laptop buruk, mungkin sedang bermasalah.', 0),
(7120, 3221, '先生は 大事な ポイントを 強調するんです。', 'Sensei wa daiji na pointo wo kyouchou suru n desu.', 'Guru menegaskan poin-poin yang penting.', 0),
(7131, 3224, '日本の文化について調べているんですが、いい情報があったら教えてください。', 'Nihon no bunka ni tsuite shirabete irun desu ga, ii jouhou ga attara oshiete kudasai.', 'Saya sedang menyelidiki tentang budaya Jepang, jika ada informasi yang bagus tolong beri tahu saya.', 1),
(7132, 3224, 'この写真を見ると、昔の日本の情景と人情を感じることができます。', 'Kono shashin wo miru to, mukashi no Nihon no joukei to ninjou wo kanjiru koto ga dekimasu.', 'Ketika melihat foto ini, saya dapat merasakan pemandangan dan perasaan kemanusiaan Jepang zaman dahulu.', 1),
(7133, 3224, '友達と話しながら、お互いの事情について話しました。', 'Tomodachi to hanashinagara, otagai no jijou ni tsuite hanashimashita.', 'Sambil berbicara dengan teman, kami membicarakan tentang keadaan satu sama lain.', 1),
(7134, 3224, 'しょうらい、いろいろな人の人情や愛情について勉強するつもりです。', 'Shourai, iroiro na hito no ninjou ya aijou ni tsuite benkyou suru tsumori desu.', 'Di masa depan, saya berniat untuk belajar tentang perasaan kemanusiaan dan kasih sayang berbagai orang.', 1),
(7135, 3224, '友達とけんかしたときは、相手の事情を考えて、同情したほうがいいかもしれません。', 'Tomodachi to kenka shita toki wa, aite no jijou wo kangaete, doujou shita hou ga ii kamoshiremasen.', 'Ketika bertengkar dengan teman, memikirkan keadaan lawan dan bersimpati mungkin lebih baik.', 1),
(7136, 3225, '旅行の 前に インターネットで 情報を 調べて おきます。', 'Ryokou no mae ni intaanetto de jouhou wo shirabete okimasu.', 'Sebelum perjalanan, memeriksa informasi di internet terlebih dahulu.', 1),
(7137, 3225, '明日 先生に 研究の 報告を するんです。', 'Ashita sensei ni kenkyuu no houkoku wo suru n desu.', 'Besok akan memberikan laporan penelitian kepada guru/dosen.', 1),
(7138, 3225, '天気予報に よると、明日は 雨が 降るでしょう。', 'Tenki yohou ni yoruto, ashita wa ame ga furu deshou.', 'Menurut prakiraan cuaca, besok kemungkinan akan turun hujan.', 1),
(7139, 3225, '大学の 広報の 仕事を 手伝おうと 思っています。', 'Daigaku no kouhou no shigoto wo tetsudaou to omotte imasu.', 'Berniat untuk membantu pekerjaan publikasi/humas universitas.', 1),
