(7571, 3244, 'あの 人は 前歴が あるかもしれません。', 'Ano hito wa zenreki ga aru kamo shiremasen.', 'Orang itu mungkin memiliki riwayat sebelumnya.', 1),
(7572, 3244, '大学で 日本の 歴史を 勉強しようと 思っています。', 'Daigaku de Nihon no rekishi wo benkyou shiyou to omotte imasu.', 'Saya berpikir untuk mempelajari sejarah Jepang di universitas.', 1),
(7573, 3244, '歴代の 社長の写真が 飾られています。', 'Rekidai no shachou no shashin ga kazararete imasu.', 'Foto-foto direktur dari generasi ke generasi dipajang.', 1),
(7574, 3245, '古い 歴史を 調べるのが 好きです。', 'Furui rekishi wo shiraberu no ga suki desu.', 'Saya suka mempelajari sejarah tua.', 1),
(7575, 3245, '図書館に 大事な 史料が 集めてあります。', 'Toshokan ni daiji na shiryou ga atsumete arimasu.', 'Bahan/dokumen sejarah penting telah dikumpulkan di perpustakaan.', 1),
(7576, 3245, '先史時代の 生活は 面白いでしょう。', 'Senshi jidai no seikatsu wa omoshiroi deshou.', 'Kehidupan di zaman prasejarah mungkin menarik.', 1),
(7577, 3245, '昔の 秘史について 調べているんです。', 'Mukashi no hishi ni tsuite shirabete iru n desu.', 'Saya sedang menyelidiki sejarah rahasia masa lalu.', 1),
(7578, 3245, 'これは 史上 最大の ニュースかもしれません。', 'Kore wa shijou saidai no nyuusu kamo shiremasen.', 'Ini mungkin berita terbesar dalam sejarah.', 1),
(7579, 3246, 'テストの 期間を 手帳に 書いて おきます。', 'Tesuto no kikan wo techou ni kaite okimasu.', 'Saya akan mencatat jangka waktu ujian di buku catatan terlebih dahulu.', 1),
(7580, 3246, '新しい 学期は 来月 始まるでしょう。', 'Atarashii gakki wa raigetsu hajimarudeshou.', 'Semester baru kemungkinan akan dimulai bulan depan.', 1),
(7581, 3246, 'いい 時期に 旅行した ほうが いいです。', 'Ii jiki ni ryokou shita hou ga ii desu.', 'Lebih baik melakukan perjalanan di waktu/periode yang baik.', 1),
(7582, 3246, '田中さんは 先生に 期待されています。', 'Tanaka-san wa sensei ni kitai sarete imasu.', 'Sdr. Tanaka diharapkan oleh guru.', 1),
(7583, 3246, '雨で 試合が 延期に なったんです。', 'Ame de shiai ga enki ni natta n desu.', 'Karena hujan, pertandingan telah ditunda.', 1);

