--
-- Struktur dari tabel `Kanji`
--

CREATE TABLE `Kanji` (
  `id` int(11) NOT NULL,
  `character` varchar(191) NOT NULL,
  `romaji` varchar(191) NOT NULL,
  `meaning` text NOT NULL,
  `moduleId` int(11) DEFAULT NULL,
  `baseMeaning` text DEFAULT NULL,
  `bushuu` varchar(191) DEFAULT NULL,
  `kunyomi` varchar(191) DEFAULT NULL,
  `onyomi` varchar(191) DEFAULT NULL,
  `isJukugo` tinyint(1) NOT NULL DEFAULT 0,
  `border` varchar(191) DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

--
-- Dumping data untuk tabel `Kanji`
--

INSERT INTO `Kanji` (`id`, `character`, `romaji`, `meaning`, `moduleId`, `baseMeaning`, `bushuu`, `kunyomi`, `onyomi`, `isJukugo`, `border`) VALUES
(3212, '試', 'shi', 'Mencoba / Menguji', 555, 'mencoba atau menguji sesuatu untuk mengetahui hasil, kemampuan, kualitas, fungsi, atau kecocokannya.', '言', 'ためす', 'シ', 0, 'border-l-4 border-primary'),
(3213, '験', 'ken', 'Mengalami, membuktikan, memverifikasi melalui pengujian', 555, 'pengalaman, pengujian, atau verifikasi.', '馬', 'tamesu', 'ケン', 0, 'border-l-4 border-secondary'),
(3214, '問', 'mon', 'bertanya, menanyakan, mempertanyakan, mempermasalahkan, mengunjungi (menengok)', 555, 'bertanya, menanyakan, mempertanyakan, atau mempermasalahkan sesuatu; dalam makna perluasannya juga dapat menunjukkan tindakan mengunjungi atau menengok.', '口', 'と（う）、と（い）', 'モン', 0, 'border-l-4 border-tertiary'),
(3215, '題', 'dai', 'Soal atau hal yang perlu diselesaikan; topik, tema, atau judul yang menunjukkan pokok suatu hal.', 555, 'soal atau hal yang perlu diselesaikan; topik, tema, atau judul yang menunjukkan pokok suatu hal.', '頁 (Oogai/Kepala, halaman)', '-', 'ダイ', 0, 'border-l-4 border-primary'),
(3216, '答', 'kota(eru)', 'menjawab, memberikan jawaban, tanggapan, atau balasan', 555, 'menjawab, memberikan jawaban, tanggapan, atau balasan terhadap pertanyaan maupun sesuatu yang diterima.', '竹 (Takekanmuri) Radikal Bambu', 'こた（える）', 'トウ', 0, 'border-l-4 border-secondary'),
(3218, '研', 'Ken', 'Mengasah / Memperdalam', 556, 'mengasah atau memperdalam suatu hal.', '石（いし・へん）', '（と）ぐ', 'ケン', 0, 'border-l-4 border-primary'),
(3219, '究', 'Kyuu', 'Mendalami / Menyelidiki Sampai Tuntas', 556, 'mendalami atau menyelidiki sesuatu sampai tuntas.', '穴（あなかんむり）', '（きわ）める', 'キュウ', 0, 'border-l-4 border-secondary'),
(3220, '集', 'Shuu / Atsumaru', 'Berkumpul / Mengumpulkan', 556, 'berkumpul, mengumpulkan, menghimpun, atau menyatukan sesuatu.', '隹 (Furutori / Burung ekor pendek)', '（あつ）まる、（あつ）める、（つど）う', 'シュウ', 0, 'border-orange-500'),
(3221, '調', 'Chou / Shiraberu', 'Mengatur, Menyesuaikan, Memeriksa, Menyelidiki', 556, 'mengatur, menyesuaikan, memeriksa, atau menyelidiki sehingga sesuatu menjadi sesuai atau seimbang.', '言 (ごんべん)', 'しらべる, ととのえる, ととのう', 'チョウ', 0, 'border-purple-500'),
(3222, '査', 'Sa', 'Menyelidiki / Memeriksa', 556, 'menyelidiki, memeriksa, atau mengecek untuk mengetahui kebenaran sesuatu.', '木 (Pohon)', '-', 'サ', 0, 'border-emerald-500'),
(3224, '情', 'jou', 'Perasaan / Emosi', 557, 'perasaan, kasih sayang, keadaan/situasi, atau informasi mengenai suatu hal.', '忄', 'なさ.け', 'ジョウ, セイ', 0, 'border-blue-500'),
(3225, '報', 'hou', 'Informasi / Berita / Membalas', 557, 'memberitahukan, menyampaikan berita atau informasi, serta membalas atau memberikan balasan.', '土', 'むく.いる', 'ホウ', 0, 'border-green-500'),
(3226, '伝', 'den', 'Menyampaikan / Mewariskan', 557, 'menyampaikan, meneruskan, mewariskan, menyebarkan, mengajarkan, dan mengirimkan sesuatu kepada pihak lain.', '亻', 'つた.わる, つた.える, つた.う', 'デン, テン', 0, 'border-red-500'),
(3227, '信', 'shin', 'Percaya / Informasi', 557, 'percaya / yakin / kebenaran, menyampaikan, meneruskan, mewariskan, menyebarkan, mengajarkan, dan mengirimkan sesuatu kepada pihak lain.', '亻', '-', 'シン', 0, 'border-blue-500'),
