(3229, '送', 'sou', 'Mengirim / Mengantarkan', 557, 'mengirim, menyampaikan, mengantarkan, mengirimkan ke suatu tempat atau kepada seseorang.', '辶', 'おく.る', 'ソウ', 0, 'border-yellow-500'),
