(1, 'Kombinasi Utama', 'Kategori gabungan kanji utama', '2026-07-30 06:16:09.358'),
(2, 'Aktivitas Pengujian', 'Kelompok ini menunjukkan makna yang berkaitan dengan kegiatan menguji kemampuan, pengetahuan, atau kelayakan melalui ujian maupun pertanyaan. Seperti terdapat pada jukugo berikut ini:', '2026-07-30 06:16:09.366'),
(3, 'Konsumsi', 'Kelompok ini menunjukkan makna yang berkaitan dengan mencoba makanan atau minuman melalui kegiatan mencicipi untuk mengetahui rasa atau kualitasnya. Seperti terdapat pada jukugo berikut ini:', '2026-07-30 06:16:09.371'),
(4, 'Ekonomi & Bisnis', 'Kategori perdagangan dan keuangan', '2026-07-30 06:16:09.373'),
