(20, 'Akademik dan Penelitian', 'Kategori Akademik dan Penelitian', '2026-07-30 06:19:16.612'),
(21, 'Teknologi dan Layanan', 'Kategori Teknologi dan Layanan', '2026-07-30 06:19:16.614'),
(22, 'Penggunaan', 'Kelompok ini menunjukkan makna yang berkaitan dengan mencoba menggunakan, mengenakan, atau menaiki sesuatu untuk mengetahui fungsi, kenyamanan, atau kecocokannya. Seperti terdapat pada jukugo berikut ini:', '2026-07-30 06:19:16.623'),
(23, 'Produksi dan Pengembangan', 'Kelompok ini menunjukkan makna yang berkaitan dengan membuat atau memproduksi sesuatu secara percobaan untuk mengetahui hasil, fungsi, atau kualitasnya sebelum dikembangkan lebih lanjut. Seperti terdapat pada jukugo berikut ini:', '2026-07-30 06:19:16.625'),
(25, 'Judul dan Tema', 'Kategori Judul dan Tema', '2026-07-30 06:19:16.641'),
(26, 'Diskusi dan Pemikiran', 'Kategori Diskusi dan Pemikiran', '2026-07-30 06:19:16.643'),
(27, 'Media dan Publikasi', 'Kategori Media dan Publikasi', '2026-07-30 06:19:16.645'),
(28, 'Pengujian', 'Kategori Pengujian', '2026-07-30 06:19:16.646'),
(29, 'Pengalaman', 'Kelompok ini menunjukkan makna yang berkaitan dengan sesuatu yang dialami atau dijalani secara langsung sehingga seseorang memperoleh pengetahuan atau pemahaman.', '2026-07-30 06:19:16.648'),
(30, 'Penelitian', 'Kategori Penelitian', '2026-07-30 06:19:16.649'),
(31, 'Sertifikasi', 'Kategori Sertifikasi', '2026-07-30 06:19:16.651'),
(32, 'Kegiatan Penelitian', 'Kelompok ini berkaitan dengan kegiatan penelitian, pelaku penelitian, serta tempat berlangsungnya penelitian.', '2026-07-31 03:45:54.652'),
(33, 'Pelatihan dan Pengembangan', 'Kelompok ini berkaitan dengan proses belajar untuk meningkatkan pengetahuan dan keterampilan.', '2026-07-31 03:45:54.654'),
(34, 'Proses Mengasah dan Memperhalus', 'Kelompok ini menunjukkan makna asli kanji 研, yaitu mengasah atau memperhalus sesuatu.', '2026-07-31 03:45:54.655'),
(35, 'Ilmu Pengetahuan dan Akademik', 'Kelompok ini berkaitan dengan hasil dan bidang penelitian dalam dunia akademik.', '2026-07-31 03:45:54.656'),
(36, 'Analisis dan Pemeriksaan', 'Kelompok ini berkaitan dengan pemeriksaan, verifikasi, dan penyelidikan masalah.', '2026-07-31 03:45:54.657'),
(37, 'Penelitian dan Penyelidikan', 'Kelompok kegiatan dan proses penelitian serta penyelidikan secara mendalam.', '2026-08-10 06:13:42.665'),
(38, 'Pencarian Penyebab', 'Kelompok penyelidikan untuk menemukan penyebab, fakta, dan kebenaran peristiwa.', '2026-08-10 06:13:42.681'),
(39, 'Akademik dan Ilmiah', 'Kelompok fasilitas, program, dan media dalam lingkungan akademik dan penelitian.', '2026-08-10 06:13:42.692'),
(40, 'Pendalaman Ilmu', 'Kelompok dorongan, rasa ingin tahu, dan semangat untuk mendalami ilmu pengetahuan.', '2026-08-10 06:13:42.705'),
(41, 'Hasil dan Pemahaman', 'Kelompok hasil pencapaian, kesimpulan, dan pemahaman hakikat tertinggi.', '2026-08-10 06:13:42.721'),
