(44, 'Pendidikan dan Akademik', 'Kelompok jukugo yang berkaitan dengan konsentrasi, daya pikir, dan perkuliahan.', '2026-08-10 06:24:48.457'),
(45, 'Buku dan Publikasi', 'Kelompok jukugo yang berkaitan dengan buku kumpulan karya, foto, puisi, dan latihan.', '2026-08-10 06:24:48.464'),
(46, 'Informasi dan Dokumentasi', 'Kelompok jukugo yang berkaitan dengan kumpulan catatan, dokumen, laporan, dan kasus.', '2026-08-10 06:24:48.470'),
(47, 'Kondisi dan Keadaan', 'Kelompok jukugo yang berkaitan dengan kondisi tubuh, keadaan, dan kesehatan.', '2026-08-10 06:32:59.730'),
