(108, 'Pengujian / Pembuktian', 'Kelompok ini menunjukkan makna yang berkaitan dengan kegiatan menguji, menjalani pengujian, atau membuktikan sesuatu melalui percobaan.', '2026-09-10 02:47:07.210'),
(109, 'Verifikasi / Pemeriksaan', 'Kelompok ini menunjukkan makna yang berkaitan dengan kegiatan memeriksa kembali untuk memastikan kebenaran suatu hasil.', '2026-09-10 02:47:07.218'),
(110, 'Hasil / Efek / Bukti', 'Kelompok ini menunjukkan makna yang berkaitan dengan hasil atau efek yang tampak dan dapat menjadi tanda atau bukti dari suatu proses.', '2026-09-10 02:47:07.221'),
(111, 'Bertanya / Mengajukan Pertanyaan', 'Kelompok ini berkaitan dengan kegiatan bertanya atau mengajukan pertanyaan kepada orang lain maupun kepada diri sendiri. Kanji 問 menunjukkan makna “bertanya atau menanyakan”. Seperti terdapat dalam jukugo berikut ini:', '2026-09-10 03:26:06.884'),
(112, 'Tanya Jawab', 'Kelompok ini berkaitan dengan kegiatan bertanya dan memberikan jawaban. Kanji 問 menunjukkan makna “bertanya”, sedangkan pasangannya menunjukkan tindakan menjawab. Seperti terdapat dalam jukugo berikut ini:', '2026-09-10 03:26:06.886'),
(113, 'Soal / Pertanyaan', 'Kelompok ini berkaitan dengan sesuatu yang menjadi pertanyaan, soal, atau masalah yang perlu dijawab maupun diselesaikan. Kanji 問 menunjukkan makna “pertanyaan atau sesuatu yang dipermasalahkan”. Seperti terdapat dalam jukugo berikut ini:', '2026-09-10 03:26:06.887'),
(114, 'Pemeriksaan dengan Pertanyaan', 'Kelompok ini berkaitan dengan kegiatan memeriksa atau memastikan sesuatu melalui pertanyaan maupun pengecekan. Kanji 問 menunjukkan makna “menanyakan”. Seperti terdapat dalam jukugo berikut ini:', '2026-09-10 03:26:06.890'),
(115, 'Mempertanyakan / Meminta Pertanggungjawaban', 'Kelompok ini berkaitan dengan kegiatan mempertanyakan, mempermasalahkan, atau meminta pertanggungjawaban mengenai suatu hal. Kanji 問 menunjukkan makna “mempertanyakan atau mempermasalahkan”. Seperti terdapat dalam jukugo berikut ini:', '2026-09-10 03:26:06.891'),
(116, 'Mengunjungi', 'Kelompok ini menunjukkan perluasan makna kanji 問 yang berkaitan dengan tindakan mengunjungi atau menengok seseorang maupun suatu tempat. Seperti terdapat dalam jukugo berikut ini:', '2026-09-10 03:26:06.892'),
(117, 'Soal / Tugas / Masalah', 'Kelompok ini menunjukkan makna yang berkaitan dengan soal, tugas, atau persoalan yang perlu diberikan, dikerjakan, dijawab, maupun diselesaikan.', '2026-09-10 03:34:09.325'),
(118, 'Tema / Topik', 'Kelompok ini menunjukkan makna yang berkaitan dengan pokok atau hal yang menjadi pusat pembicaraan, pemikiran, pembahasan, maupun diskusi.', '2026-09-10 03:34:09.330'),
(119, 'Judul', 'Kelompok ini menunjukkan makna yang berkaitan dengan judul, penamaan, atau tulisan yang menunjukkan isi suatu karya, tulisan, maupun presentasi. Seperti terdapat dalam jukugo berikut ini:', '2026-09-10 03:34:09.333'),
(120, 'Bahan / Tema Karya', 'Kelompok ini menunjukkan makna yang berkaitan dengan bahan, pokok, atau tema yang digunakan sebagai dasar untuk menghasilkan suatu karya.', '2026-09-10 03:34:09.336'),
(121, 'Jawaban / Tanggapan', 'Kelompok ini menunjukkan makna jawaban, tanggapan, atau balasan terhadap pertanyaan maupun sesuatu yang diterima.', '2026-09-10 03:57:36.413'),
(122, 'Hasil Jawaban', 'Kelompok ini menunjukkan makna yang berkaitan dengan jawaban sebagai hasil dari proses menjawab, memecahkan persoalan, atau menentukan jawaban. Seperti pada jukugo berikut ini:', '2026-09-10 03:57:36.417'),
(123, 'Cara Menjawab', 'Kelompok ini menunjukkan makna yang berkaitan dengan cara atau bentuk ketika seseorang memberikan jawaban. Seperti berikut ini:', '2026-09-10 03:57:36.418'),
(124, 'Balasan', 'Kelompok ini menunjukkan makna yang berkaitan dengan tindakan membalas ucapan, penghormatan, atau perlakuan yang diterima dari orang lain. Seperti pada jukugo berikut ini:', '2026-09-10 03:57:36.420'),
(125, 'Meneliti / Mendalami', 'Kelompok ini menunjukkan makna yang berkaitan dengan kegiatan meneliti, mempelajari, atau mendalami suatu ilmu maupun hal tertentu.', '2026-09-10 06:09:03.723'),
(126, 'Belajar / Mengasah Kemampuan', 'Kelompok ini menunjukkan makna yang berkaitan dengan kegiatan belajar, berlatih, atau mengembangkan pengetahuan dan kemampuan.', '2026-09-10 06:09:03.726'),
(127, 'Mengasah / Menghaluskan', 'Kelompok ini menunjukkan makna yang berkaitan dengan tindakan mengasah, memoles, atau menghaluskan suatu benda.', '2026-09-10 06:09:03.728'),
(128, 'Meneliti / Menyelidiki', 'Kelompok ini menunjukkan makna yang berkaitan dengan kegiatan meneliti, mencari, atau menelusuri suatu hal secara mendalam sampai memperoleh pemahaman atau kejelasan.', '2026-09-10 06:13:55.903'),
(129, 'Mengkaji / Membahas', 'Kelompok ini menunjukkan makna yang berkaitan dengan kegiatan memikirkan, menelaah, atau membahas suatu hal secara mendalam.', '2026-09-10 06:13:55.906'),
(130, 'Mendalami / Mengungkap', 'Kelompok ini menunjukkan makna yang berkaitan dengan kegiatan mendalami prinsip atau mengungkap suatu hal sampai menjadi jelas.', '2026-09-10 06:13:55.907'),
(131, 'Berkumpul / Berkelompok', 'Kelompok ini menunjukkan makna yang berkaitan dengan orang atau benda yang berkumpul, berhimpun, atau membentuk suatu kelompok.', '2026-09-10 06:19:30.934'),
(132, 'Mengumpulkan / Menghimpun', 'Kelompok ini menunjukkan makna yang berkaitan dengan tindakan mengumpulkan, mengambil, menghimpun, atau memanggil sesuatu maupun seseorang agar terkumpul.', '2026-09-10 06:19:30.962'),
(133, 'Memusatkan / Mengakumulasi', 'Kelompok ini menunjukkan makna yang berkaitan dengan sesuatu yang dikumpulkan, dipusatkan, ditumpuk, atau dihimpun menjadi satu.', '2026-09-10 06:19:30.971'),
(134, 'Kumpulan / Hasil yang Dihimpun', 'Kelompok ini menunjukkan makna yang berkaitan dengan hasil dari berbagai karya atau bahan yang telah dikumpulkan dan dihimpun menjadi satu kumpulan.', '2026-09-10 06:19:30.974'),
(135, 'Memeriksa', 'Kelompok ini menunjukkan makna yang berkaitan dengan kegiatan memeriksa atau meneliti sesuatu untuk mengetahui keadaan atau kebenarannya.', '2026-09-10 06:33:04.836'),
(136, 'Memeriksa dengan Teliti', 'Kelompok ini menunjukkan makna yang berkaitan dengan kegiatan memeriksa sesuatu secara teliti, rinci, dan mendalam.', '2026-09-10 06:33:04.838'),
(137, 'Menilai', 'Kelompok ini menunjukkan makna yang berkaitan dengan kegiatan memeriksa sesuatu untuk memberikan penilaian atau menentukan hasil.', '2026-09-10 06:33:04.839'),
(138, 'Menyelidiki', 'Kelompok ini menunjukkan makna yang berkaitan dengan kegiatan menyelidiki suatu hal untuk memperoleh keterangan atau mengetahui keadaan yang sebenarnya.', '2026-09-10 06:33:04.841'),
(139, 'Menguji', 'Kelompok ini menunjukkan makna yang berkaitan dengan kegiatan memeriksa melalui pengujian untuk memastikan suatu keadaan atau hasil.', '2026-09-10 06:33:04.842'),
(140, 'Profesi / Pekerjaan', 'Kelompok ini menunjukkan makna yang berkaitan dengan pekerjaan, profesi, atau orang yang memiliki keterampilan tertentu dalam pekerjaannya.', '2026-09-10 09:26:55.318'),
(141, 'Orang / Tempat Kerja', 'Kelompok ini menunjukkan makna yang berkaitan dengan orang yang bekerja dan tempat berlangsungnya kegiatan pekerjaan.', '2026-09-10 09:26:55.330'),
(142, 'Mencari / Memiliki Pekerjaan', 'Kelompok ini menunjukkan makna yang berkaitan dengan usaha mencari pekerjaan dan keadaan memiliki pekerjaan.', '2026-09-10 09:26:55.338'),
(143, 'Perubahan / Status Pekerjaan', 'Kelompok ini menunjukkan makna yang berkaitan dengan perubahan keadaan seseorang dalam pekerjaan, termasuk berpindah, berhenti, atau tidak memiliki pekerjaan.', '2026-09-10 09:26:55.347'),
(144, 'Pekerjaan / Tugas', 'Kelompok ini menunjukkan makna yang berkaitan dengan pekerjaan, tugas, kegiatan kerja, serta pelaksanaan suatu pekerjaan.', '2026-09-10 09:26:55.374'),
(145, 'Usaha / Bisnis / Dunia Kerja', 'Kelompok ini menunjukkan makna yang berkaitan dengan kegiatan usaha, bisnis, perusahaan, pelaku usaha, dan lingkungan dunia kerja.', '2026-09-10 09:26:55.388'),
(146, 'Bidang Industri / Pekerjaan', 'Kelompok ini menunjukkan makna yang berkaitan dengan berbagai bidang industri, pekerjaan, usaha, dan kegiatan ekonomi.', '2026-09-10 09:26:55.404'),
(147, 'Bentuk / Status Pekerjaan', 'Kelompok ini menunjukkan makna yang berkaitan dengan kedudukan atau bentuk pekerjaan yang menjadi kegiatan utama seseorang.', '2026-09-10 09:26:55.415'),
(148, 'Tempat Perdagangan', 'Kelompok ini berkaitan dengan tempat berlangsungnya kegiatan perdagangan atau tempat yang digunakan untuk melakukan kegiatan jual beli.', '2026-09-10 09:26:55.436'),
(149, 'Produk / Barang Dagangan', 'Kelompok ini berkaitan dengan barang atau produk yang diperjualbelikan dalam kegiatan perdagangan.', '2026-09-10 09:26:55.441'),
(150, 'Kegiatan Perdagangan', 'Kelompok ini berkaitan dengan kegiatan, transaksi, atau aktivitas yang dilakukan dalam perdagangan dan bisnis.', '2026-09-10 09:26:55.445'),
(151, 'Pelaku Perdagangan', 'Kelompok ini berkaitan dengan orang yang melakukan kegiatan perdagangan atau menjalankan aktivitas bisnis.', '2026-09-10 09:26:55.451'),
(152, 'Jenis Usaha', 'Kelompok ini berkaitan dengan bentuk atau jenis usaha yang bergerak dalam bidang perdagangan dan bisnis.', '2026-09-10 09:26:55.454'),
(153, 'Tugas / Kewajiban', 'Kelompok ini menunjukkan makna yang berkaitan dengan tugas yang diberikan, kewajiban, atau tanggung jawab yang harus dilaksanakan.', '2026-09-10 09:26:55.479'),
(154, 'Urusan / Pelaksanaan Tugas', 'Kelompok ini menunjukkan makna yang berkaitan dengan pelaksanaan tugas atau urusan pekerjaan dalam bidang tertentu.', '2026-09-10 09:26:55.486'),
(155, 'Bidang / Urusan Tugas', 'Kelompok ini menunjukkan makna yang berkaitan dengan urusan atau tugas yang berada dalam bidang pekerjaan tertentu.', '2026-09-10 09:26:55.492'),
(156, 'Teknik / Keterampilan', 'Kelompok ini menunjukkan makna yang berkaitan dengan teknik, keterampilan, atau cara khusus untuk melakukan suatu tindakan.', '2026-09-10 09:26:55.511'),
(157, 'Ilmu / Pengetahuan', 'Kelompok ini menunjukkan makna yang berkaitan dengan ilmu, pengetahuan, atau metode keilmuan tertentu.', '2026-09-10 09:26:55.519'),
(158, 'Seni / Keahlian Seni', 'Kelompok ini menunjukkan makna yang berkaitan dengan seni dan keterampilan untuk menghasilkan karya seni.', '2026-09-10 09:26:55.523'),
(159, 'Pengalaman / Proses', 'Kelompok ini menunjukkan makna yang berkaitan dengan sesuatu yang dialami atau dilalui dalam suatu proses maupun perjalanan kehidupan.', '2026-09-10 09:45:34.917'),
(160, 'Jalur / Cara Melalui', 'Kelompok ini menunjukkan makna yang berkaitan dengan jalur, perantara, atau cara sesuatu dilakukan atau disampaikan.', '2026-09-10 09:45:34.931'),
(161, 'Pengelolaan / Ekonomi', 'Kelompok ini menunjukkan makna yang berkaitan dengan pengelolaan, penyelenggaraan, dan penggunaan sumber daya dalam kegiatan ekonomi.', '2026-09-10 09:45:34.939'),
(162, 'Awal Waktu', 'Kelompok ini menunjukkan makna yang berkaitan dengan awal suatu rentang waktu.', '2026-09-10 09:45:34.981'),
(163, 'Mulai / Mengawali', 'Kelompok ini menunjukkan makna yang berkaitan dengan dimulainya suatu kegiatan, pekerjaan, atau gerakan.', '2026-09-10 09:45:34.984'),
(164, 'Awal dan Akhir', 'Kelompok ini menunjukkan makna yang berkaitan dengan keseluruhan rentang suatu keadaan dari awal hingga akhir.', '2026-09-10 09:45:34.994'),
(165, 'Penyelesaian', 'Kelompok ini menunjukkan makna yang berkaitan dengan penanganan suatu urusan sampai pada bagian akhirnya.', '2026-09-10 09:45:35.000'),
(166, 'Riwayat Pendidikan / Pekerjaan', 'Kelompok ini menunjukkan makna yang berkaitan dengan riwayat atau perjalanan seseorang dalam pendidikan dan pekerjaan.', '2026-09-10 09:45:35.027'),
(167, 'Riwayat Kehidupan', 'Kelompok ini menunjukkan makna yang berkaitan dengan catatan atau perjalanan suatu keadaan yang telah terjadi sebelumnya.', '2026-09-10 09:45:35.039'),
(168, 'Sejarah / Perjalanan Waktu', 'Kelompok ini menunjukkan makna yang berkaitan dengan perjalanan suatu masa dan peristiwa yang telah berlangsung dari waktu ke waktu.', '2026-09-10 09:45:35.050'),
(169, 'Masa / Sejarah', 'Kelompok ini menunjukkan makna yang berkaitan dengan sejarah dan masa yang mendahului atau menjadi bagian dari sejarah.', '2026-09-10 09:45:35.084'),
(170, 'Fakta / Sumber Sejarah', 'Kelompok ini menunjukkan makna yang berkaitan dengan fakta dan bahan yang digunakan untuk mengetahui atau mempelajari sejarah.', '2026-09-10 09:45:35.094'),
(171, 'Jenis / Sifat Sejarah', 'Kelompok ini menunjukkan makna yang berkaitan dengan sifat atau jenis catatan sejarah.', '2026-09-10 09:45:35.102'),
(172, 'Dalam Sejarah', 'Kelompok ini menunjukkan makna yang berkaitan dengan sesuatu yang terjadi atau dikenal dalam perjalanan sejarah.', '2026-09-10 09:45:35.108'),
(173, 'Waktu / Periode', 'Kelompok ini menunjukkan makna yang berkaitan dengan waktu, rentang waktu, jangka waktu, atau periode tertentu.', '2026-09-10 09:45:35.135'),
(174, 'Tahap Waktu', 'Kelompok ini menunjukkan makna yang berkaitan dengan bagian atau tahap tertentu dalam suatu periode.', '2026-09-10 09:45:35.161'),
(175, 'Batas Waktu', 'Kelompok ini menunjukkan makna yang berkaitan dengan waktu yang telah ditentukan, batas penyerahan, penundaan, atau berakhirnya suatu periode.', '2026-09-10 09:45:35.184'),
(176, 'Harapan / Perkiraan', 'Kelompok ini menunjukkan makna yang berkaitan dengan sesuatu yang diharapkan atau diperkirakan akan terjadi.', '2026-09-10 09:45:35.199'),
(177, 'Bahan Pengujian', 'Kelompok ini menunjukkan makna yang berkaitan dengan bahan yang digunakan dalam proses pemeriksaan atau pengujian. Seperti terdapat pada jukugo berikut ini:', '2026-09-14 09:26:49.675'),
(178, 'Kompetisi dan Keterampilan', 'Kelompok ini menunjukkan makna yang berkaitan dengan pengujian atau pembandingan kemampuan dan keterampilan melalui pertandingan maupun pelaksanaan suatu teknik. Seperti terdapat pada jukugo berikut ini:', '2026-09-14 09:26:49.681'),
(179, 'Media', 'Kelompok ini menunjukkan makna yang berkaitan dengan mencoba melihat, mendengarkan, atau membaca suatu karya atau media sebelum dinikmati atau digunakan lebih lanjut. Seperti terdapat pada jukugo berikut ini:', '2026-09-14 09:26:49.687'),
(180, 'Mengunjungi (Makna Perluasan)', 'Kelompok ini menunjukkan perluasan makna kanji 問 yang berkaitan dengan tindakan mengunjungi atau menengok seseorang maupun suatu tempat.', '2026-09-14 09:27:09.395'),
