(237, '1. Pengalaman / Perjalanan Waktu', 'Kelompok ini menunjukkan makna yang berkaitan dengan sesuatu yang dialami atau dilalui dalam suatu proses maupun perjalanan kehidupan.', '2026-09-14 09:29:34.173'),
(238, '2. Jalur / Cara Melalui', 'Kelompok ini menunjukkan makna yang berkaitan dengan jalur, perantara, atau cara sesuatu dilakukan atau disampaikan.', '2026-09-14 09:29:34.213'),
(239, '3. Ekonomi / Pengelolaan', 'Kelompok ini menunjukkan makna yang berkaitan dengan pengelolaan, penyelenggaraan, dan penggunaan sumber daya dalam kegiatan ekonomi.', '2026-09-14 09:29:34.221'),
(240, '1. AWAL WAKTU', 'Kelompok ini menunjukkan makna yang berkaitan dengan awal suatu rentang waktu.', '2026-09-14 09:29:34.254'),
(241, '2. MULAI', 'Kelompok ini menunjukkan makna yang berkaitan dengan dimulainya suatu kegiatan, pekerjaan, atau gerakan.', '2026-09-14 09:29:34.258'),
(242, '3. AWAL-AKHIR', 'Kelompok ini menunjukkan makna yang berkaitan dengan keseluruhan rentang suatu keadaan dari awal hingga akhir.', '2026-09-14 09:29:34.267'),
(243, '4. PENYELESAIAN', 'Kelompok ini menunjukkan makna yang berkaitan dengan penanganan suatu urusan sampai pada bagian akhirnya.', '2026-09-14 09:29:34.273'),
(244, '1. RIWAYAT', 'Kelompok ini menunjukkan makna yang berkaitan dengan riwayat atau perjalanan seseorang dalam pendidikan dan pekerjaan.', '2026-09-14 09:29:34.299'),
(245, '2. KEHIDUPAN', 'Kelompok ini menunjukkan makna yang berkaitan dengan catatan atau perjalanan suatu keadaan yang telah terjadi sebelumnya.', '2026-09-14 09:29:34.308'),
(246, '3. SEJARAH', 'Kelompok ini menunjukkan makna yang berkaitan dengan perjalanan suatu masa dan peristiwa yang telah berlangsung dari waktu ke waktu.', '2026-09-14 09:29:34.316'),
(247, '1. SEJARAH', 'Kelompok ini menunjukkan makna yang berkaitan dengan sejarah dan masa yang mendahului atau menjadi bagian dari sejarah.', '2026-09-14 09:29:34.347'),
(248, '2. FAKTA', 'Kelompok ini menunjukkan makna yang berkaitan dengan fakta sejarah.', '2026-09-14 09:29:34.356'),
(249, '3. SUMBER', 'Kelompok ini menunjukkan makna yang berkaitan dengan bahan atau sumber sejarah.', '2026-09-14 09:29:34.359'),
(250, '4. JENIS SEJARAH', 'Kelompok ini menunjukkan makna yang berkaitan dengan sifat atau jenis catatan sejarah.', '2026-09-14 09:29:34.363'),
(251, '5. DALAM SEJARAH', 'Kelompok ini menunjukkan makna yang berkaitan dengan sesuatu yang terjadi atau dikenal dalam perjalanan sejarah.', '2026-09-14 09:29:34.369'),
