ricScore\":0,\"groupingRatio\":0},{\"question\":\"Jukugo mana yang berhubungan dengan makna “efek atau khasiat yang menunjukkan suatu hasil”?\",\"type\":\"multiple\",\"studentAnswer\":\"効験\",\"correctAnswer\":\"効験\",\"isCorrect\":true,\"rubricScore\":0,\"groupingRatio\":0},{\"question\":\"Jukugo mana yang berhubungan dengan makna “pengalaman yang diperoleh dari sesuatu yang telah dijalani”?\",\"type\":\"multiple\",\"studentAnswer\":\"実験\",\"correctAnswer\":\"経験\",\"isCorrect\":false,\"rubricScore\":0,\"groupingRatio\":0},{\"question\":\"Jukugo mana yang berhubungan dengan makna “uji klinis untuk mengetahui efektivitas dan keamanan obat”?\",\"type\":\"multiple\",\"studentAnswer\":\"試験\",\"correctAnswer\":\"治験\",\"isCorrect\":false,\"rubricScore\":0,\"groupingRatio\":0},{\"question\":\"Jukugo mana yang berhubungan dengan makna “mengikuti atau menjalani suatu ujian”?\",\"type\":\"multiple\",\"studentAnswer\":\"受験\",\"correctAnswer\":\"受験\",\"isCorrect\":true,\"rubricScore\":0,\"groupingRatio\":0},{\"question\":\"日本へいって、色々な（　　　　）をしました。\",\"type\":\"fill\",\"studentAnswer\":\"経験\",\"correctAnswer\":\"経験\",\"isCorrect\":true,\"rubricScore\":0,\"groupingRatio\":0},{\"question\":\"大学の化学の授業では、学生が（　　　　）を行いました。\",\"type\":\"fill\",\"studentAnswer\":\"受験\",\"correctAnswer\":\"実験\",\"isCorrect\":false,\"rubricScore\":0,\"groupingRatio\":0},{\"question\":\"明日は大切な（　　　　）がありますから、今晩勉強しなければなりません。\",\"type\":\"fill\",\"studentAnswer\":\"試験\",\"correctAnswer\":\"試験\",\"isCorrect\":true,\"rubricScore\":0,\"groupingRatio\":0},{\"question\":\"この薬には（　　　　）があるかもしれません。\",\"type\":\"fill\",\"studentAnswer\":\"試験\",\"correctAnswer\":\"効験\",\"isCorrect\":false,\"rubricScore\":0,\"groupingRatio\":0}]', '2026-09-15 01:48:28.507');

