(14838, 3284, 'Hubungan makna antar kanji 採 dan 点, saat digabungkan menjadi 採点, menunjukan bahwa gabungan kedua kanji itu mengandung makna \'kegiatan memberikan nilai terhadap hasil pekerjaan\'', NULL),
