(15347, 3220, 'Hubungan makna antar kanji 募 dan 集 menjadi 募集, menunjukkan bahwa gabungan kedua kanji tersebut membentuk makna “mencari atau mengajak orang agar terkumpul untuk suatu tujuan.”', 15803),
(15348, 3220, 'Hubungan makna antar kanji 招 dan 集 menjadi 招集, menunjukkan bahwa gabungan kedua kanji tersebut membentuk makna “memanggil atau mengundang orang agar berkumpul pada suatu tempat.”', 15804),
(15349, 3220, 'Hubungan makna antar kanji 集 dan 中 menjadi 集中, menunjukkan bahwa gabungan kedua kanji tersebut membentuk makna “mengumpulkan atau memusatkan perhatian maupun sesuatu pada satu titik atau sasaran.”', 15805),
(15350, 3220, 'Hubungan makna antar kanji 集 dan 積 menjadi 集積, menunjukkan bahwa gabungan kedua kanji tersebut membentuk makna “mengumpulkan sesuatu sehingga menumpuk atau terakumulasi.”', 15806),
(15351, 3220, 'Hubungan makna antar kanji 集 dan 成 menjadi 集成, menunjukkan bahwa gabungan kedua kanji tersebut membentuk makna “menghimpun berbagai unsur dan membentuknya menjadi satu kesatuan.”', 15807),
(15352, 3220, 'Hubungan makna antar kanji 全 dan 集 menjadi 全集, menunjukkan bahwa gabungan kedua kanji tersebut membentuk makna “kumpulan lengkap dari seluruh karya atau tulisan tertentu.”', 15808),
(15353, 3220, 'Hubungan makna antar kanji 選 dan 集 menjadi 選集, menunjukkan bahwa gabungan kedua kanji tersebut membentuk makna “kumpulan karya atau tulisan yang dipilih dan dihimpun menjadi satu.”', 15809),
(15546, 3224, 'Hubungan makna antar kanji 感 dan 情 menjadi 感情, menunjukkan bahwa gabungan kedua kanji tersebut membentuk makna “perasaan atau emosi yang dirasakan oleh seseorang.”', 16002),
(15547, 3224, 'Hubungan makna antar kanji 表 dan 情 menjadi 表情, menunjukkan bahwa gabungan kedua kanji tersebut membentuk makna “perasaan atau emosi yang tampak pada raut wajah seseorang.”', 16003),
(15548, 3224, 'Hubungan makna antar kanji 心 dan 情 menjadi 心情, menunjukkan bahwa gabungan kedua kanji tersebut membentuk makna “perasaan yang ada di dalam hati atau suasana batin seseorang.”', 16004),
(15549, 3224, 'Hubungan makna antar kanji 真 dan 情 menjadi 真情, menunjukkan bahwa gabungan kedua kanji tersebut membentuk makna “perasaan yang sesungguhnya atau ungkapan perasaan yang jujur.”', 16005),
(15550, 3224, 'Hubungan makna antar kanji 純 dan 情 menjadi 純情, menunjukkan bahwa gabungan kedua kanji tersebut membentuk makna “perasaan yang murni, polos, dan tulus tanpa kepentingan tertentu.”', 16006),
(15551, 3224, 'Hubungan makna antar kanji 愛 dan 情 menjadi 愛情, menunjukkan bahwa gabungan kedua kanji tersebut membentuk makna “perasaan cinta atau kasih sayang yang diberikan kepada seseorang atau sesuatu.”', 16007),
(15552, 3224, 'Hubungan makna antar kanji 友 dan 情 menjadi 友情, menunjukkan bahwa gabungan kedua kanji tersebut membentuk makna “perasaan kasih dan kedekatan yang terjalin antar teman.”', 16008),
(15553, 3224, 'Hubungan makna antar kanji 同 dan 情 menjadi 同情, menunjukkan bahwa gabungan kedua kanji tersebut membentuk makna “merasakan atau memahami perasaan orang lain karena memiliki perasaan yang sama terhadap keadaan yang dialaminya.”', 16009),
(15554, 3224, 'Hubungan makna antar kanji 人 dan 情 menjadi 人情, menunjukkan bahwa gabungan kedua kanji tersebut membentuk makna “perasaan kemanusiaan, kasih sayang, dan kepedulian yang muncul dalam hubungan antarmanusia.”', 16010),
(15555, 3224, 'Hubungan makna antar kanji 交 dan 情 menjadi 交情, menunjukkan bahwa gabungan kedua kanji tersebut membentuk makna “hubungan dekat yang terbentuk melalui pergaulan dan perasaan saling mengenal.”', 16011),
(15556, 3224, 'Hubungan makna antar kanji 情 dan 熱 menjadi 情熱, menunjukkan bahwa gabungan kedua kanji tersebut membentuk makna “perasaan atau semangat yang sangat kuat terhadap seseorang, kegiatan, atau sesuatu yang diminati.”', 16012),
(15557, 3224, 'Hubungan makna antar kanji 熱 dan 情 menjadi 熱情, menunjukkan bahwa gabungan kedua kanji tersebut membentuk makna “perasaan yang kuat dan penuh semangat terhadap seseorang atau sesuatu.”', 16013),
(15558, 3224, 'Hubungan makna antar kanji 事 dan 情 menjadi 事情, menunjukkan bahwa gabungan kedua kanji tersebut membentuk makna “keadaan atau latar belakang yang berkaitan dengan suatu peristiwa atau masalah.”', 16014),
(15559, 3224, 'Hubungan makna antar kanji 実 dan 情 menjadi 実情, menunjukkan bahwa gabungan kedua kanji tersebut membentuk makna “keadaan yang sebenarnya atau kondisi nyata dari suatu hal.”', 16015),
(15560, 3224, 'Hubungan makna antar kanji 内 dan 情 menjadi 内情, menunjukkan bahwa gabungan kedua kanji tersebut membentuk makna “keadaan atau kondisi yang terdapat di dalam suatu organisasi, kelompok, atau masalah.”', 16016),
(15561, 3224, 'Hubungan makna antar kanji 情 dan 勢 menjadi 情勢, menunjukkan bahwa gabungan kedua kanji tersebut membentuk makna “keadaan atau situasi yang sedang berlangsung pada suatu waktu tertentu.”', 16017),
(15562, 3224, 'Hubungan makna antar kanji 情 dan 景 menjadi 情景, menunjukkan bahwa gabungan kedua kanji tersebut membentuk makna “gambaran suatu keadaan, suasana, atau pemandangan yang dapat dilihat atau dibayangkan.”', 16018),
(15563, 3224, 'Hubungan makna antar kanji 苦 dan 情 menjadi 苦情, menunjukkan bahwa gabungan kedua kanji tersebut membentuk makna “ungkapan ketidakpuasan atau keluhan terhadap suatu keadaan, pelayanan, atau tindakan tertentu.”', 16019),
(15564, 3224, 'Hubungan makna antar kanji 情 dan 報 menjadi 情報, menunjukkan bahwa gabungan kedua kanji tersebut membentuk makna “informasi atau data mengenai suatu keadaan, peristiwa, atau hal tertentu yang disampaikan kepada seseorang.”', 16020),
(15565, 3225, 'Hubungan makna antar kanji 情 dan 報 menjadi 情報, menunjukkan bahwa gabungan kedua kanji tersebut membentuk makna “informasi atau keterangan mengenai suatu hal.”', 16021),
(15566, 3225, 'Hubungan makna antar kanji 報 dan 知 menjadi 報知, menunjukkan bahwa gabungan kedua kanji tersebut membentuk makna “memberitahukan atau menyampaikan sesuatu agar diketahui oleh orang lain.”', 16022),
(15567, 3225, 'Hubungan makna antar kanji 報 dan 告 menjadi 報告, menunjukkan bahwa gabungan kedua kanji tersebut membentuk makna “menyampaikan atau memberitahukan hasil, keadaan, atau informasi mengenai suatu kegiatan kepada pihak lain.”', 16023),
(15568, 3225, 'Hubungan makna antar kanji 予 dan 報 menjadi 予報, menunjukkan bahwa gabungan kedua kanji tersebut membentuk makna “informasi atau pemberitahuan mengenai sesuatu yang diperkirakan akan terjadi.”', 16024),
(15569, 3225, 'Hubungan makna antar kanji 通 dan 報 menjadi 通報, menunjukkan bahwa gabungan kedua kanji tersebut membentuk makna “menyampaikan atau melaporkan suatu informasi kepada pihak tertentu.”', 16025),
(15570, 3225, 'Hubungan makna antar kanji 速 dan 報 menjadi 速報, menunjukkan bahwa gabungan kedua kanji tersebut membentuk makna “berita atau informasi yang disampaikan dengan cepat mengenai suatu peristiwa yang baru terjadi.”', 16026),
(15571, 3225, 'Hubungan makna antar kanji 続 dan 報 menjadi 続報, menunjukkan bahwa gabungan kedua kanji tersebut membentuk makna “berita atau informasi lanjutan mengenai suatu peristiwa yang telah diberitakan sebelumnya.”', 16027),
(15572, 3225, 'Hubungan makna antar kanji 特 dan 報 menjadi 特報, menunjukkan bahwa gabungan kedua kanji tersebut membentuk makna “berita atau informasi yang disampaikan secara khusus karena memiliki sifat atau kepentingan tertentu.”', 16028),
(15573, 3225, 'Hubungan makna antar kanji 悲 dan 報 menjadi 悲報, menunjukkan bahwa gabungan kedua kanji tersebut membentuk makna “berita yang membawa atau menyampaikan kabar duka atau kesedihan.”', 16029),
(15574, 3225, 'Hubungan makna antar kanji 勝 dan 報 menjadi 勝報, menunjukkan bahwa gabungan kedua kanji tersebut membentuk makna “berita yang menyampaikan kemenangan atau hasil yang baik dalam suatu pertandingan atau peristiwa.”', 16030),
(15575, 3225, 'Hubungan makna antar kanji 日 dan 報 menjadi 日報, menunjukkan bahwa gabungan kedua kanji tersebut membentuk makna “laporan atau informasi yang dibuat atau disampaikan setiap hari.”', 16031),
(15576, 3225, 'Hubungan makna antar kanji 広 dan 報 menjadi 広報, menunjukkan bahwa gabungan kedua kanji tersebut membentuk makna “informasi atau pemberitaan yang disampaikan secara luas kepada masyarakat.”', 16032),
(15577, 3225, 'Hubungan makna antar kanji 公 dan 報 menjadi 公報, menunjukkan bahwa gabungan kedua kanji tersebut membentuk makna “pemberitahuan atau berita yang disampaikan secara resmi kepada masyarakat atau untuk kepentingan umum.”', 16033),
(15578, 3225, 'Hubungan makna antar kanji 確 dan 報 menjadi 確報, menunjukkan bahwa gabungan kedua kanji tersebut membentuk makna “berita atau laporan yang kebenarannya telah dipastikan.”', 16034),
(15579, 3225, 'Hubungan makna antar kanji 会 dan 報 menjadi 会報, menunjukkan bahwa gabungan kedua kanji tersebut membentuk makna “buletin atau laporan yang berisi informasi mengenai kegiatan suatu organisasi atau perkumpulan.”', 16035),
(15580, 3225, 'Hubungan makna antar kanji 時 dan 報 menjadi 時報, menunjukkan bahwa gabungan kedua kanji tersebut membentuk makna “pemberitahuan mengenai waktu yang disampaikan pada waktu-waktu tertentu secara berkala.”', 16036),
(15581, 3225, 'Hubungan makna antar kanji 返 dan 報 menjadi 返報, menunjukkan bahwa gabungan kedua kanji tersebut membentuk makna “memberikan balasan atau mengembalikan suatu tindakan yang telah diterima.”', 16037),
(15582, 3225, 'Hubungan makna antar kanji 報 dan 復 menjadi 報復, menunjukkan bahwa gabungan kedua kanji tersebut membentuk makna “melakukan pembalasan terhadap suatu tindakan atau perlakuan yang telah diterima.”', 16038),
(15583, 3225, 'Hubungan makna antar kanji 電 dan 報 menjadi 電報, menunjukkan bahwa gabungan kedua kanji tersebut membentuk makna “penyampaian berita atau pesan melalui sarana komunikasi listrik/telegraf.”', 16039),
(15584, 3225, 'Hubungan makna antar kanji 外 dan 報 menjadi 外報, menunjukkan bahwa gabungan kedua kanji tersebut membentuk makna “berita atau informasi yang berasal dari luar negeri atau dari luar suatu wilayah.”', 16040),
(15585, 3225, 'Hubungan makna antar kanji 報 dan 道 menjadi 報道, menunjukkan bahwa gabungan kedua kanji tersebut membentuk makna “kegiatan menyampaikan atau memberitakan informasi mengenai suatu peristiwa kepada masyarakat.”', 16041),
(15586, 3226, 'Hubungan makna antar kanji 伝 dan 言 menjadi 伝言, menunjukkan bahwa penyampaian dilakukan melalui kata atau ucapan, sehingga membentuk makna “pesan atau titipan pesan.”', 16042),
(15587, 3226, 'Hubungan makna antar kanji 伝 dan 達 menjadi 伝達, menunjukkan proses menyampaikan sesuatu hingga informasi tersebut sampai kepada pihak lain, sehingga membentuk makna “penyampaian atau penyebaran informasi.”', 16043),
(15588, 3226, 'Hubungan makna antar kanji 伝 dan 聞 menjadi 伝聞, menunjukkan informasi yang diteruskan melalui apa yang didengar, sehingga membentuk makna “kabar yang didengar dari orang lain.”', 16044),
(15589, 3226, 'Hubungan makna antar kanji 伝 dan 令 menjadi 伝令, menunjukkan seseorang yang menyampaikan perintah atau instruksi kepada pihak lain, sehingga membentuk makna “pembawa atau penyampai pesan/perintah.”', 16045),
(15590, 3226, 'Hubungan makna antar kanji 伝 dan 授 menjadi 伝授, menunjukkan proses meneruskan atau mewariskan pengetahuan/keterampilan dengan cara mengajarkannya, sehingga membentuk makna “mengajarkan atau mewariskan ilmu/keterampilan.”', 16046),
(15591, 3226, 'Hubungan makna antar kanji 伝 dan 受 menjadi 伝受, menunjukkan proses menerima sesuatu yang diteruskan atau diwariskan, sehingga membentuk makna “menerima dan meneruskan sesuatu.”', 16047),
(15592, 3226, 'Hubungan makna antar kanji 伝 dan 習 menjadi 伝習, menunjukkan kegiatan mempelajari sesuatu yang telah diwariskan atau diteruskan, sehingga membentuk makna “mempelajari sesuatu yang diwariskan/diajarkan.”', 16048),
(15593, 3226, 'Hubungan makna antar kanji 伝 dan 道 menjadi 伝道, menunjukkan kegiatan menyampaikan atau meneruskan ajaran atau doktrin, sehingga membentuk makna “menyebarkan atau menyampaikan ajaran.”', 16049),
(15594, 3226, 'Hubungan makna antar kanji 伝 dan 統 menjadi 伝統, menunjukkan sesuatu yang diteruskan dan dipertahankan sebagai satu kesatuan dari generasi ke generasi, sehingga membentuk makna “tradisi.”', 16050),
(15595, 3226, 'Hubungan makna antar kanji 伝 dan 説 menjadi 伝説, menunjukkan cerita atau penjelasan yang diteruskan dan diwariskan dari generasi ke generasi, sehingga membentuk makna “legenda.”', 16051),
(15596, 3226, 'Hubungan makna antar kanji 伝 dan 記 menjadi 伝記, menunjukkan riwayat seseorang yang disampaikan melalui catatan tertulis, sehingga membentuk makna “biografi atau riwayat hidup.”', 16052),
(15597, 3226, 'Hubungan makna antar kanji 自 dan 伝 menjadi 自伝, menunjukkan riwayat tentang diri sendiri yang disampaikan atau dituliskan, sehingga membentuk makna “autobiografi.”', 16053),
(15598, 3226, 'Hubungan makna antar kanji 伝 dan 書 menjadi 伝書, menunjukkan tulisan atau dokumen yang diteruskan atau diwariskan, sehingga membentuk makna “tulisan/dokumen yang diwariskan atau disampaikan.”', 16054),
(15599, 3226, 'Hubungan makna antar kanji 伝 dan 写 menjadi 伝写, menunjukkan proses meneruskan isi tulisan dengan cara menyalin atau menggandakannya, sehingga membentuk makna “menyalin atau meneruskan tulisan.”', 16055);
INSERT INTO `SemanticRelation` (`id`, `kanjiId`, `penjelasan`, `jukugoId`) VALUES
(15600, 3226, 'Hubungan makna antar kanji 伝 dan 送 menjadi 伝送, menunjukkan sesuatu yang diteruskan atau disampaikan melalui proses pengiriman, sehingga membentuk makna “pengiriman atau transmisi.”', 16056),
(15601, 3227, 'Hubungan makna antar kanji 信 dan 言 menjadi 信言, menunjukkan bahwa perkataan atau ucapan yang disampaikan dapat dipercaya kebenarannya.', 16057),
(15602, 3227, 'Hubungan makna antar kanji 通 dan 信 menjadi 通信, menunjukkan bahwa gabungan kedua kanji tersebut membentuk makna “proses penyampaian atau pertukaran informasi antar pihak yang satu dengan pihak lainnya.”', 16058),
(15603, 3227, 'Hubungan makna antar kanji 発 dan 信 menjadi 発信, menunjukkan bahwa gabungan kedua kanji tersebut membentuk makna “mengirimkan atau menyampaikan informasi dari suatu pihak kepada pihak lain.”', 16059),
(15604, 3227, 'Hubungan makna antar kanji 送 dan 信 menjadi 送信, menunjukkan bahwa gabungan kedua kanji tersebut membentuk makna “mengirimkan pesan, informasi, atau data kepada pihak lain.”', 16060),
(15605, 3227, 'Hubungan makna antar kanji 返 dan 信 menjadi 返信, menunjukkan bahwa gabungan kedua kanji tersebut membentuk makna “mengirimkan kembali pesan atau surat sebagai balasan.”', 16061),
(15606, 3227, 'Hubungan makna antar kanji 交 dan 信 menjadi 交信, menunjukkan bahwa gabungan kedua kanji tersebut membentuk makna “saling bertukar pesan atau informasi antar dua pihak atau lebih.”', 16062),
(15607, 3227, 'Hubungan makna antar kanji 信 dan 号 menjadi 信号, menunjukkan bahwa gabungan kedua kanji tersebut membentuk makna “tanda atau isyarat yang digunakan untuk menyampaikan informasi atau pesan tertentu.”', 16063),
(15608, 3227, 'Hubungan makna antar kanji 信 dan 念 menjadi 信念, menunjukkan bahwa gabungan kedua kanji tersebut membentuk makna “keyakinan yang dipegang dengan kuat dan tidak mudah berubah.”', 16064),
(15609, 3227, 'Hubungan makna antar kanji 信 dan 者 menjadi 信者, menunjukkan bahwa gabungan kedua kanji tersebut membentuk makna “orang yang percaya atau menganut suatu kepercayaan.”', 16065),
(15610, 3227, 'Hubungan makna antar kanji 信 dan 徒 menjadi 信徒, menunjukkan bahwa gabungan kedua kanji tersebut membentuk makna “orang yang mengikuti atau menganut suatu kepercayaan atau agama.”', 16066),
(15611, 3227, 'Hubungan makna antar kanji 信 dan 頼 menjadi 信頼, menunjukkan bahwa gabungan kedua kanji tersebut membentuk makna “kepercayaan terhadap seseorang atau sesuatu yang dianggap dapat diandalkan.”', 16067),
(15612, 3227, 'Hubungan makna antar kanji 信 dan 用 menjadi 信用, menunjukkan bahwa gabungan kedua kanji tersebut membentuk makna “kepercayaan atau penilaian bahwa seseorang atau sesuatu dapat dipercaya.”', 16068),
(15613, 3227, 'Hubungan makna antar kanji 信 dan 任 menjadi 信任, menunjukkan bahwa gabungan kedua kanji tersebut membentuk makna “memberikan kepercayaan kepada seseorang untuk menjalankan tugas atau tanggung jawab.”', 16069),
(15614, 3227, 'Hubungan makna antar kanji 信 dan 義 menjadi 信義, menunjukkan bahwa gabungan kedua kanji tersebut membentuk makna “kepercayaan dan kesetiaan yang didasarkan pada kebenaran atau prinsip moral.”', 16070),
(15615, 3227, 'Hubungan makna antar kanji 確 dan 信 menjadi 確信, menunjukkan bahwa gabungan kedua kanji tersebut membentuk makna “keyakinan yang kuat atau kepastian terhadap sesuatu.”', 16071),
(15616, 3227, 'Hubungan makna antar kanji 自 dan 信 menjadi 自信, menunjukkan bahwa gabungan kedua kanji tersebut membentuk makna “kepercayaan terhadap diri sendiri atau percaya pada kemampuan diri.”', 16072),
(15617, 3227, 'Hubungan makna antar kanji 信 dan 書 menjadi 信書, menunjukkan bahwa gabungan kedua kanji tersebut membentuk makna “surat atau dokumen tertulis yang digunakan untuk menyampaikan pesan dari seseorang kepada orang lain.”', 16073),
(15618, 3229, 'Hubungan makna antar kanji 送 dan 信 menjadi 送信, menunjukkan bahwa gabungan kedua kanji tersebut membentuk makna “mengirim pesan atau mengirimkan data/informasi.”', 16074),
(15619, 3229, 'Hubungan makna antar kanji 電 dan 送 menjadi 電送, menunjukkan bahwa gabungan kedua kanji tersebut membentuk makna “pengiriman melalui media elektronik atau transmisi elektronik.”', 16075),
(15620, 3229, 'Hubungan makna antar kanji 伝 dan 送 menjadi 伝送, menunjukkan bahwa gabungan kedua kanji tersebut membentuk makna “meneruskan atau mentransmisikan informasi/sinyal.”', 16076),
(15621, 3229, 'Hubungan makna antar kanji 放 dan 送 menjadi 放送, menunjukkan bahwa gabungan kedua kanji tersebut membentuk makna siaran atau penyebaran informasi kepada banyak orang.”', 16077),
(15622, 3229, 'Hubungan makna antar kanji 発 dan 送 menjadi 発送, menunjukkan bahwa gabungan kedua kanji tersebut membentuk makna “mengirim atau mengeluarkan kiriman.”', 16078),
(15623, 3229, 'Hubungan makna antar kanji 直 dan 送 menjadi 直送, menunjukkan bahwa gabungan kedua kanji tersebut membentuk makna “pengiriman langsung ke tujuan.”', 16079),
(15624, 3229, 'Hubungan makna antar kanji 送 dan 付 menjadi 送付, menunjukkan bahwa gabungan kedua kanji tersebut membentuk makna “mengirimkan barang, dokumen, surat, dan sebagainya.”', 16080),
(15625, 3229, 'Hubungan makna antar kanji 郵 dan 送 menjadi 郵送, menunjukkan bahwa gabungan kedua kanji tersebut membentuk makna “mengirim melalui pos atau surat.”', 16081),
(15626, 3229, 'Hubungan makna antar kanji 配 dan 送 menjadi 配送, menunjukkan bahwa gabungan kedua kanji tersebut membentuk makna “pengiriman barang, paket, atau pesanan.”', 16082),
(15627, 3229, 'Hubungan makna antar kanji 輸 dan 送 menjadi 輸送, menunjukkan bahwa gabungan kedua kanji tersebut membentuk makna “mengangkut atau mengirim barang atau penumpang.”', 16083),
(15628, 3229, 'Hubungan makna antar kanji 移 dan 送 menjadi 移送, menunjukkan bahwa gabungan kedua kanji tersebut membentuk makna “memindahkan atau mengirim ke tempat lain.”', 16084),
(15629, 3229, 'Hubungan makna antar kanji 回 dan 送 menjadi 回送, menunjukkan bahwa gabungan kedua kanji tersebut membentuk makna “mengirim kembali atau mengirim ke tempat asal/tempat lain.”', 16085),
(15630, 3229, 'Hubungan makna antar kanji 転 dan 送 menjadi 転送, menunjukkan bahwa gabungan kedua kanji tersebut membentuk “meneruskan atau mengalihkan kiriman ke tujuan lain.”', 16086),
(15631, 3229, 'Hubungan makna antar kanji 押 dan 送 menjadi 押送, menunjukkan bahwa gabungan kedua kanji tersebut membentuk makna “mengawal atau mengantar seseorang dengan kendaraan resmi.”', 16087),
