(15815, 3246, 'Hubungan makna antar kanji 短 dan 期 menjadi 短期, menunjukkan bahwa gabungan kedua kanji tersebut membentuk makna “periode atau jangka waktu yang pendek.”', 16271),
(15816, 3246, 'Hubungan makna antar kanji 定 dan 期 menjadi 定期, menunjukkan bahwa gabungan kedua kanji tersebut membentuk makna “sesuatu yang berlangsung pada periode yang telah ditentukan atau secara berkala.”', 16272),
(15817, 3246, 'Hubungan makna antar kanji 周 dan 期 menjadi 周期, menunjukkan bahwa gabungan kedua kanji tersebut membentuk makna “periode yang berulang secara teratur sehingga membentuk suatu siklus.”', 16273),
(15818, 3246, 'Hubungan makna antar kanji 学 dan 期 menjadi 学期, menunjukkan bahwa gabungan kedua kanji tersebut membentuk makna “periode tertentu dalam kegiatan pendidikan atau semester.”', 16274),
(15819, 3246, 'Hubungan makna antar kanji 会 dan 期 menjadi 会期, menunjukkan bahwa gabungan kedua kanji tersebut membentuk makna “periode atau masa berlangsungnya suatu sidang.”', 16275),
(15820, 3246, 'Hubungan makna antar kanji 初 dan 期 menjadi 初期, menunjukkan bahwa gabungan kedua kanji tersebut membentuk makna “periode atau tahap awal.”', 16276),
(15821, 3246, 'Hubungan makna antar kanji 前 dan 期 menjadi 前期, menunjukkan bahwa gabungan kedua kanji tersebut membentuk makna “periode sebelumnya atau bagian awal dari suatu rangkaian periode.”', 16277),
(15822, 3246, 'Hubungan makna antar kanji 後 dan 期 menjadi 後期, menunjukkan bahwa gabungan kedua kanji tersebut membentuk makna “periode setelahnya atau bagian akhir dari suatu rangkaian periode.”', 16278),
(15823, 3246, 'Hubungan makna antar kanji 早 dan 期 menjadi 早期, menunjukkan bahwa gabungan kedua kanji tersebut membentuk makna “periode atau tahap yang masih awal.”', 16279),
(15824, 3246, 'Hubungan makna antar kanji 期 dan 首 menjadi 期首, menunjukkan bahwa gabungan kedua kanji tersebut membentuk makna “bagian awal dari suatu periode.”', 16280),
(15825, 3246, 'Hubungan makna antar kanji 期 dan 末 menjadi 期末, menunjukkan bahwa gabungan kedua kanji tersebut membentuk makna “bagian akhir dari suatu periode.”', 16281),
(15826, 3246, 'Hubungan makna antar kanji 末 dan 期 menjadi 末期, menunjukkan bahwa gabungan kedua kanji tersebut membentuk makna “periode atau tahap yang berada pada bagian akhir.”', 16282),
(15827, 3246, 'Hubungan makna antar kanji 期 dan 限 menjadi 期限, menunjukkan bahwa gabungan kedua kanji tersebut membentuk makna “batas waktu yang telah ditentukan.”', 16283),
(15828, 3246, 'Hubungan makna antar kanji 期 dan 日 menjadi 期日, menunjukkan bahwa gabungan kedua kanji tersebut membentuk makna “hari atau tanggal yang telah ditentukan.”', 16284),
(15829, 3246, 'Hubungan makna antar kanji 納 dan 期 menjadi 納期, menunjukkan bahwa gabungan kedua kanji tersebut membentuk makna “batas waktu yang ditentukan untuk menyerahkan sesuatu.”', 16285),
(15830, 3246, 'Hubungan makna antar kanji 延 dan 期 menjadi 延期, menunjukkan bahwa gabungan kedua kanji tersebut membentuk makna “menunda suatu kegiatan atau waktu ke periode yang lebih kemudian.”', 16286),
(15831, 3246, 'Hubungan makna antar kanji 満 dan 期 menjadi 満期, menunjukkan bahwa gabungan kedua kanji tersebut membentuk makna “berakhirnya periode yang telah ditentukan atau saat jatuh tempo.”', 16287),
(15832, 3246, 'Hubungan makna antar kanji 期 dan 待 menjadi 期待, menunjukkan bahwa gabungan kedua kanji tersebut membentuk makna “harapan terhadap sesuatu yang dinantikan atau diharapkan terjadi.”', 16288),
(15833, 3246, 'Hubungan makna antar kanji 予 dan 期 menjadi 予期, menunjukkan bahwa gabungan kedua kanji tersebut membentuk makna “memperkirakan atau mengharapkan sesuatu akan terjadi.”', 16289);

